<script setup>
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import { RefreshCw, Settings2, ShieldCheck, Database, ChevronLeft, ChevronRight, Download, Search, X, Link, AlertCircle } from 'lucide-vue-next'
import { api, downloadFile } from '../api'
import ConfigNav from './ConfigNav.vue'
const userMode=ref('current'),userFilter=ref('positive'),balances=ref(null),balanceAt=ref('0'),balanceQuery=ref('')
const visibleUsers=computed(()=>userFilter.value==='positive'?browseRows.value.filter(r=>r.status==='active'&&Number(r.balance)>0):browseRows.value)
const browseRows=ref([]),browseMore=ref(false),browseBefore=ref(0),browseUser=ref(''),browseBusy=ref(false)
let browseController
const progress=ref(null),backfillDate=ref('')
const tab=ref('report'),section=ref('connection'),config=ref(null),report=ref(null),status=ref(null),error=ref(''),notice=ref(''),busy=ref('')
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const mode=ref('day'),date=ref(today()),start=ref(today()+'T00:00'),end=ref(today()+'T23:59'),query=ref(''),state=ref(''),page=ref(1),size=ref(20)
const selected=ref(null),detail=ref([]),entity=ref('usage'),detailBusy=ref(false),detailBefore=ref(0),detailMore=ref(false)
let disposed=false,timer,controller,detailController,generation=0,searchTimer
const params=()=>new URLSearchParams({mode:mode.value,date:date.value,start:start.value,end:end.value,query:query.value,state:state.value,page:String(page.value),page_size:String(size.value)})
const money=v=>v===null||v===undefined?'—':Number(v).toLocaleString('en-US',{minimumFractionDigits:4,maximumFractionDigits:10})
const time=v=>v?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(typeof v==='number'?v*1000:v)):'—'
const states={review:'需核实',unknown:'证据不足 / 待结算',consistent:'快照区间一致'}
const pages=computed(()=>Math.max(1,Math.ceil((report.value?.total||0)/size.value)))
const syncFields=[['interval_seconds','自动同步间隔（秒）',10,86400,'保存不立即执行，下一轮使用新配置'],['history_days','首次同步历史（天）',1,3650,'首次接入生效；历史补录可在下方单独执行'],['batch_size','每批明细条数',100,10000,'分批增量读取，默认2000'],['max_batches','每轮最多批数',1,1000,'大表和小表轮流同步'],['segment_minutes','查询时间分段（分钟）',1,60,'支持1/2/3/4/5/6/10/12/15/20/30/60'],['round_seconds','每轮最长时间（秒）',5,300,'超过后保留已完成进度'],['query_seconds','单次查询超时（秒）',1,60,'限制源数据库查询时间'],['pause_ms','批次间隔（毫秒）',0,60000,'增大可降低源数据库压力'],['overlap_minutes','近期回扫范围（分钟）',1,1440,'补齐近期延迟落库，按来源及ID更新不重复累计'],['settlement_seconds','结算等待（秒）',0,86400,'近期请求等待结算后再同步核对'],['retry_seconds','失败后重试间隔（秒）',10,86400,'失败保留进度，下轮续传']]
const retentionFields=[['backup_interval_seconds','用户余额备份间隔（秒）',60,86400,'使用已同步的独立用户快照，不额外查询 sub2api'],['backup_retention_days','用户余额备份保留（天）',1,3650,'仅备份启用且余额大于0的用户，可在用户账户查看和导出'],['detail_days','明细保留（天）',1,3650,'压缩保存明细；到期清理不影响已累计的汇总'],['retention_days','快照与运行日志保留（天）',1,3650,'每日汇总长期保留，清理不会反向修改源数据'],['refresh_seconds','页面刷新（秒）',5,3600,'只读取Space本地数据'],['persistence_seconds','稳定快照间隔（秒）',0,86400,'稳定快照至少相隔此时间后才能核对']]
const rules=[['check_billing','请求与计费凭据双向核对'],['check_charges','用量、零费用和费用倍率核对'],['check_funding','充值、赠送、返利和退款来源核对'],['check_balance','独立余额快照与收支核对'],['check_quota','Key额度耗尽后继续使用的线索核对']]
async function loadBalances(){try{balances.value=await api('/api/client-audit/balances?'+new URLSearchParams({at:balanceAt.value,query:balanceQuery.value}))}catch(e){error.value=e.message}}
async function exportBalances(){await action('export-balances',()=>downloadFile('/api/client-audit/balances?'+new URLSearchParams({at:String(balances.value?.at||balanceAt.value),query:balanceQuery.value,export:'csv'}),'用户余额快照.csv'))}
watch(userFilter,()=>loadBrowse())
watch([userMode,balanceAt],()=>{if(userMode.value==='backup')loadBalances()})
async function loadBrowse(more=false){if(disposed||!['users','usage'].includes(tab.value))return;browseController?.abort();const request=new AbortController();browseController=request;browseBusy.value=true;if(!more){browseRows.value=[];browseBefore.value=0}
try{const q=new URLSearchParams({mode:'all',entity:tab.value==='users'?'user':'usage',user_id:tab.value==='users'?'0':(browseUser.value||'0'),before:String(browseBefore.value),filter:tab.value==='users'?userFilter.value:''});const r=await api('/api/client-audit/detail?'+q,{signal:request.signal});if(request.signal.aborted||disposed)return;browseRows.value=more?[...browseRows.value,...r.items]:r.items;browseMore.value=r.items.length===100;if(r.items.length)browseBefore.value=r.items.at(-1).id}catch(e){if(!request.signal.aborted)error.value=e.message}finally{if(browseController===request)browseBusy.value=false}}
watch(tab,()=>{browseController?.abort();selected.value=null;detailController?.abort();if(['users','usage'].includes(tab.value))loadBrowse();if(tab.value==='users'&&userMode.value==='backup')loadBalances()})
async function load(){if(disposed)return;controller?.abort();const request=new AbortController();controller=request;const version=++generation;clearTimeout(timer)
 try{const [r,s,p]=await Promise.all([api('/api/client-audit/report?'+params(),{signal:request.signal}),api('/api/client-audit/status',{signal:request.signal}),api('/api/client-audit/progress',{signal:request.signal})]);if(disposed||version!==generation)return;report.value=r;status.value=s;progress.value=p;error.value=''}catch(e){if(!disposed&&!request.signal.aborted)error.value=e.message}
 finally{if(!disposed&&version===generation)timer=setTimeout(load,(config.value?.refresh_seconds||30)*1000)}
}
async function action(name,fn){if(busy.value)return;busy.value=name;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=''}}
async function save(){await action('save',async()=>{config.value={...await api('/api/client-audit/settings',{method:'PUT',body:config.value}),db_password:''};notice.value='已保存。不会立即同步；下轮采用新配置。';report.value=null;await load()})}
async function test(kind){await action('test-'+kind,async()=>{const r=await api('/api/client-audit/test?kind='+kind,{method:'POST',body:config.value,timeoutMs:70000});notice.value=[r.message,r.warning].filter(Boolean).join(' ')})}
async function sync(){await action('sync',async()=>{const r=await api('/api/client-audit/sync',{method:'POST'});notice.value=r.message;await load()})}
const entityNames={usage:'使用明细',billing:'计费凭据',funding:'充值 / 调整',affiliate:'返利',payment:'支付 / 退款',audit:'管理审计'}
async function backfill(){await action('backfill',async()=>{const r=await api('/api/client-audit/backfill',{method:'POST',body:{date:backfillDate.value}});notice.value=r.message;await load()})}
async function stop(){await action('stop',async()=>{const r=await api('/api/client-audit/stop',{method:'POST'});notice.value=r.message;await load()})}
async function exportCSV(){await action('export',()=>downloadFile('/api/client-audit/export?'+params(),'客户端对账.csv'))}
function shift(n){const d=new Date(date.value+'T12:00:00+08:00');if(mode.value==='month')d.setUTCMonth(d.getUTCMonth()+n);else d.setUTCDate(d.getUTCDate()+n*(mode.value==='week'?7:1));date.value=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
async function open(row){selected.value=row;detailBefore.value=0;await loadDetail()}
async function loadDetail(more=false){if(!selected.value||disposed)return;detailController?.abort();detailController=new AbortController();const request=detailController;detailBusy.value=true;if(!more){detail.value=[];detailBefore.value=0}
 try{const q=params();q.set('user_id',selected.value.id);q.set('entity',entity.value);q.set('before',String(detailBefore.value));const r=await api('/api/client-audit/detail?'+q,{signal:request.signal});if(request.signal.aborted||disposed)return;detail.value=more?[...detail.value,...r.items]:r.items;detailMore.value=r.items.length===100;if(r.items.length)detailBefore.value=r.items.at(-1).id}catch(e){if(!request.signal.aborted)error.value=e.message}finally{if(detailController===request)detailBusy.value=false}}
watch(entity,()=>loadDetail());watch([mode,date,start,end,state,size],()=>{report.value=null;page.value=1;selected.value=null;detailController?.abort();load()});watch(page,()=>{report.value=null;load()});watch(query,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{report.value=null;page.value=1;load()},250)})
onMounted(async()=>{try{config.value={...await api('/api/client-audit/settings'),db_password:''};await load()}catch(e){error.value=e.message}})
onBeforeUnmount(()=>{disposed=true;controller?.abort();browseController?.abort();detailController?.abort();clearTimeout(timer);clearTimeout(searchTimer)})
</script>

<template>
 <div class="audit-page">
  <header class="heading"><div><span class="eyebrow">SUB2API DATA</span><h1>Sub2Api</h1><p>客户端数据同步、使用查询与资金对账。</p></div><div class="actions"><button class="btn ghost" :disabled="!!busy" @click="sync"><RefreshCw :size="15"/>立即增量同步</button><button class="btn ghost" @click="tab=tab==='settings'?'report':'settings'"><Settings2 :size="15"/>{{tab==='settings'?'返回对账':'连接与同步设置'}}</button></div></header>
  <nav class="module-tabs" aria-label="Sub2Api 页面"><button v-for="[key,label] in [['report','客户端对账'],['users','用户账户'],['usage','使用记录'],['history','同步记录'],['settings','连接与同步设置']]" :key="key" :class="{active:tab===key}" @click="tab=key">{{label}}</button></nav>
  <div v-if="error" class="message error" role="alert">{{error}}</div><div v-if="notice" class="message" role="status">{{notice}}</div>
  <div class="source-strip"><ShieldCheck :size="16"/><span>{{config?.name||'尚未连接客户端'}} · <b>源端只查询</b></span><span>{{status?.running?'正在增量同步':config?.enabled?'自动同步已开启':'自动同步已关闭'}}</span><span>数据截止 {{time(status?.through)}}</span><span>Space 数据 {{((status?.db_bytes||0)/1048576).toFixed(1)}} MB</span></div>
  <div v-if="status?.error" class="message error">上轮同步：{{status.error}}。已同步数据保留，后续断点续传。</div>
  <template v-if="tab==='settings' && config">
   <ConfigNav v-model="section" label="客户端对账设置" :items="[['connection','连接配置','客户端 · 只读数据库'],['sync','增量同步','批量 · 间隔 · 限速'],['rules','对账规则','金额 · 异常判定'],['retention','数据保留','明细 · 快照 · 刷新']]"/>
   <form @submit.prevent="save" class="panel config">
    <section v-show="section==='connection'"><h2><Link :size="18"/>连接配置</h2><p>连接对客户收费的 sub2api，与 Pro 推送到号池的设置独立。不调用客户端业务写接口；数据库强制只读事务，所有同步数据写入 Space。</p><div class="fields"><label>显示名称<input v-model="config.name"/></label><label>客户端地址<input v-model="config.url" placeholder="https://sub2.example.com"/></label></div>
     <h3>数据库只读连接</h3><p>完整同步需要只读数据库连接。不会给 sub2api 安装插件、增加接口或修改表结构。优先使用已有的专用只读账号。</p><div class="fields"><label>数据库地址<input v-model="config.db_host" placeholder="内网地址或服务名"/></label><label>端口<input v-model.number="config.db_port" type="number" min="1" max="65535"/></label><label>数据库名<input v-model="config.db_name"/></label><label>数据库用户<input v-model="config.db_user" autocomplete="off"/></label><label>数据库密码<input v-model="config.db_password" type="password" autocomplete="new-password" :placeholder="config.db_password_present?'已保存，留空保持':'数据库连接密码'"/></label><label>TLS<select v-model="config.ssl_mode"><option value="require">加密连接</option><option value="verify-full">校验证书及主机</option><option value="disable">内网无 TLS</option></select></label></div><button class="btn ghost" type="button" :disabled="!!busy" @click="test('database')">测试只读连接</button><p class="note">密码只在服务端加密保存，不回传浏览器。切换数据库地址、端口或库名会使用独立数据范围，避免混账。</p>
    </section>
    <section v-show="section==='sync'"><h2><Database :size="18"/>增量同步</h2><label class="check"><input type="checkbox" v-model="config.enabled"/>开启后台自动同步</label><p>使用明细、计费凭据、资金流水按时间＋ID分批续传；用户、Key及套餐保存快照。不同数据源独立记录进度，同一条记录重复读取不会重复累计。</p><div class="fields"><label v-for="[key,label,min,max,hint] in syncFields" :key="key">{{label}}<input type="number" v-model.number="config[key]" :min="min" :max="max" required/><small>{{hint}}</small></label></div><h3>历史补录</h3><p>在明细保留期内补齐历史，不重复累计。补录期间重新建立独立余额快照。</p><div class="date"><input type="date" v-model="backfillDate" :max="today()"/><button class="btn ghost" type="button" :disabled="!!busy||!backfillDate||status?.running" @click="backfill">补录历史</button><button class="btn ghost" type="button" :disabled="!!busy||!status?.running" @click="stop">停止本轮</button></div><h3>同步进度</h3><div class="table-wrap"><table><thead><tr><th>数据</th><th>续传位置</th><th>完成截止</th></tr></thead><tbody><tr v-for="(cursor,key) in progress?.cursors" :key="key"><td>{{entityNames[key]||key}}</td><td>{{time(cursor.at)}} · #{{cursor.id}}</td><td>{{time(cursor.through)}}</td></tr></tbody></table></div><h3>最近30轮</h3><div class="table-wrap"><table><thead><tr><th>开始</th><th>行数</th><th>结果</th></tr></thead><tbody><tr v-for="(run,index) in progress?.runs" :key="index"><td>{{time(run.started)}}</td><td>{{run.rows}}</td><td>{{run.message||'本轮完成，按游标继续'}}</td></tr></tbody></table></div></section>
    <section v-show="section==='rules'"><h2><ShieldCheck :size="18"/>对账规则</h2><label v-for="[key,label] in rules" :key="key" class="check"><input type="checkbox" v-model="config[key]"/>{{label}}</label><div class="fields"><label>金额容差（USD）<input v-model="config.difference_usd" inputmode="decimal"/><small>默认0.000001，内部按10位金额精度核对</small></label></div><p>没有独立余额快照、仍在结算、源数据缺失或存在返利/退款等未解释来源时，显示待核实。标记异常不代表用户恶意；页面不会自动补扣、退款、封号或修改额度。</p></section>
    <section v-show="section==='retention'"><h2>数据保留</h2><div class="fields"><label v-for="[key,label,min,max,hint] in retentionFields" :key="key">{{label}}<input type="number" v-model.number="config[key]" :min="min" :max="max" required/><small>{{hint}}</small></label></div><p>首次不会复制整个源数据库。明细压缩保存于独立 client-audit.db；清理只针对 Space 本地副本。超出明细保留期仍可看日汇总，但逐笔证据会标注不完整。</p></section>
    <footer><span>保存仅更新 Space 配置，不触发立即同步。</span><button class="btn primary" :disabled="!!busy">{{busy==='save'?'保存中…':'保存设置'}}</button></footer>
   </form>
  </template>
  <template v-else-if="tab==='history'"><section class="panel config"><h2>同步记录</h2><p>仅展示 Space 同步任务。停止本轮保留断点；关闭自动同步可暂停后续轮次。</p><button class="btn ghost" :disabled="!!busy||!status?.running" @click="stop">停止本轮</button><div class="table-wrap"><table><thead><tr><th>数据</th><th>续传位置</th><th>完成截止</th></tr></thead><tbody><tr v-for="(cursor,key) in progress?.cursors" :key="key"><td>{{entityNames[key]||key}}</td><td>{{time(cursor.at)}} · #{{cursor.id}}</td><td>{{time(cursor.through)}}</td></tr></tbody></table></div><h3>最近30轮</h3><div class="table-wrap"><table><thead><tr><th>开始 / 完成</th><th>本轮读取</th><th>结果</th></tr></thead><tbody><tr v-for="(run,index) in progress?.runs" :key="index"><td>{{time(run.started)}}<small>{{time(run.finished)}}</small></td><td>{{run.rows}} 行</td><td>{{run.message||'本轮完成，按游标继续'}}</td></tr></tbody></table></div></section></template>
  <template v-else-if="tab==='users'||tab==='usage'"><div v-if="tab==='users'" class="module-tabs"><button :class="{active:userMode==='current'}" @click="userMode='current'">当前用户</button><button :class="{active:userMode==='backup'}" @click="userMode='backup'">历史余额快照</button></div><section v-if="tab==='users'&&userMode==='backup'" class="panel"><div class="toolbar"><h2>用户余额快照</h2><select v-model="balanceAt"><option value="0">最新快照</option><option v-for="run in balances?.runs" :key="run.at" :value="String(run.at)">{{time(run.at)}} · {{run.users}} 人 · ${{money(run.balance)}}</option></select><input v-model="balanceQuery" placeholder="邮箱 / 用户ID"/><button class="btn ghost" @click="loadBalances">查询</button><button class="btn ghost" :disabled="!!busy||!balances?.at" @click="exportBalances">导出快照</button></div><p class="notes" style="padding:0 20px">仅包含快照时已启用且余额大于0的用户。共 {{balances?.total||0}} 人，余额合计 ${{money(balances?.balance)}}；记录时间 {{time(balances?.at)}}。只存 Space，不会回写余额。</p><div class="table-wrap"><table><thead><tr><th>用户</th><th>备份余额 USD</th><th>冻结 USD</th><th>累计充值字段 USD</th></tr></thead><tbody><tr v-for="row in balances?.items" :key="row.id"><td>{{row.email}}<small>#{{row.id}}</small></td><td>{{money(row.balance)}}</td><td>{{money(row.frozen)}}</td><td>{{money(row.recharged)}}</td></tr><tr v-if="!balances?.items?.length"><td colspan="4" class="empty">暂无符合条件的余额快照</td></tr></tbody></table></div></section><section v-else class="panel"><div class="toolbar"><h2>{{tab==='users'?'用户账户':'使用记录'}}</h2><select v-if="tab==='users'" v-model="userFilter"><option value="positive">已启用且有余额</option><option value="all">全部用户</option></select><label v-if="tab==='usage'">用户 ID <input v-model="browseUser" inputmode="numeric" placeholder="全部用户"/></label><button class="btn ghost" :disabled="browseBusy" @click="loadBrowse()">查询 / 刷新</button><small>只读 Space 本地副本 · 每页100条</small></div><div class="table-wrap"><table><thead><tr v-if="tab==='users'"><th>用户</th><th>状态</th><th>余额 USD</th><th>冻结 USD</th><th>累计充值字段 USD</th><th>源端更新时间</th></tr><tr v-else><th>记录 / 用户</th><th>时间</th><th>模型</th><th>输入 / 输出 Token</th><th>实际费用 USD</th><th>计费方式</th></tr></thead><tbody><tr v-for="row in (tab==='users'?visibleUsers:browseRows)" :key="row.id"><template v-if="tab==='users'"><td>{{row.email}}<small>#{{row.id}}</small></td><td>{{row.status}}</td><td>{{money(row.balance)}}</td><td>{{money(row.frozen_balance)}}</td><td>{{money(row.total_recharged)}}</td><td>{{time(row.updated_at)}}</td></template><template v-else><td>#{{row.id}}<small>用户 #{{row.user_id}} · Key #{{row.api_key_id}}</small></td><td>{{time(row.created_at)}}</td><td>{{row.model}}</td><td>{{row.input_tokens}} / {{row.output_tokens}}<small>缓存读 {{row.cache_read_tokens||0}}</small></td><td>{{money(row.actual_cost)}}<small>原价 {{money(row.total_cost)}} × {{row.rate_multiplier}}</small></td><td>{{row.billing_type===1?'套餐':'余额'}}<small>{{row.inbound_endpoint}}</small></td></template></tr><tr v-if="!(tab==='users'?visibleUsers:browseRows).length"><td colspan="6" class="empty">{{browseBusy?'正在读取…':'暂无已同步数据'}}</td></tr></tbody></table></div><footer><span>已显示 {{browseRows.length}} 条</span><button v-if="browseMore" :disabled="browseBusy" @click="loadBrowse(true)">加载更多</button></footer></section></template>
  <template v-else>
   <div class="period"><div class="period-switch"><button v-for="[key,label] in [['day','每天'],['week','每周'],['month','每月'],['all','全部'],['custom','自定义']]" :key="key" :class="{active:mode===key}" @click="mode=key">{{label}}</button></div><div v-if="mode!=='custom'&&mode!=='all'" class="date"><button @click="shift(-1)" aria-label="上一期"><ChevronLeft :size="18"/></button><input type="date" v-model="date"/><button @click="shift(1)" aria-label="下一期"><ChevronRight :size="18"/></button><button @click="date=today()">今天</button></div><div v-if="mode==='custom'" class="date"><input type="datetime-local" v-model="start"/><span>至</span><input type="datetime-local" v-model="end"/></div></div>
   <div v-if="!config?.db_host" class="empty panel"><Database :size="28"/><h2>连接你的 sub2api 客户端</h2><p>在 Space 保存独立连接后，开始增量同步和对账。</p><button class="btn primary" @click="tab='settings'">配置连接</button></div>
   <template v-if="report"><div class="cards"><button class="hero" @click="state=''">本期消费<strong>${{money(report.cost)}}</strong><small>{{report.requests.toLocaleString()}} 次请求 · 以客户端实际费用记录为准</small></button><button class="hero" @click="state=''">本期入账<strong>${{money(report.credits)}}</strong><small>充值、调整及返利转入，不等同实收现金</small></button><button class="hero warning" @click="state='review'">需核实用户<strong>{{report.abnormal}}</strong><small>未解释快照差额绝对值 ${{money(report.difference)}}</small></button><button class="hero" @click="state='unknown'">待核实 / 待结算<strong>{{report.unknown}}</strong><small>{{report.consistent}} 个用户快照区间一致</small></button></div>
    <div class="notes"><p v-for="note in report.notes" :key="note"><AlertCircle :size="13"/>{{note}}</p><p>同步覆盖：{{time(status?.start)}} 至 {{time(status?.through)}} · {{status?.coverage==='complete'?'已完成本轮范围':'等待同步 / 历史补录中'}}</p></div>
    <section class="panel"><div class="toolbar"><div class="search"><Search :size="15"/><input v-model="query" placeholder="搜索客户端用户邮箱 / ID"/></div><select v-model="state"><option value="">全部状态</option><option value="review">需核实</option><option value="unknown">证据不足 / 待结算</option><option value="consistent">快照区间一致</option></select><button class="btn ghost" :disabled="!!busy" @click="exportCSV"><Download :size="14"/>导出</button></div><div class="table-wrap"><table><thead><tr><th>客户端用户</th><th>请求数</th><th>消费 / 入账 USD</th><th>当前余额 USD</th><th>快照余额核对</th><th>核对结果</th></tr></thead><tbody><tr v-for="row in report.rows" :key="row.id" @click="open(row)" tabindex="0" @keydown.enter="open(row)"><td><b>{{row.email}}</b><small>#{{row.id}}</small></td><td>{{row.requests.toLocaleString()}}</td><td>{{money(row.cost)}}<small>入账 {{money(row.credits)}}</small></td><td>{{row.balance==='—'?'—':money(row.balance)}}</td><td v-if="row.difference!==null">{{money(row.opening)}} → {{money(row.closing)}}<small :class="{negative:Number(row.difference)!==0}">差额 {{money(row.difference)}}</small><small>{{time(row.snapshot_from)}}—{{time(row.snapshot_to)}}</small></td><td v-else>—<small>等待独立稳定快照</small></td><td><span class="pill" :class="row.state">{{states[row.state]}}</span><small v-for="reason in row.reasons.slice(0,2)" :key="reason">{{reason}}</small></td></tr><tr v-if="!report.rows.length"><td colspan="6" class="empty">当前范围暂无记录；可查看同步进度或调整筛选。</td></tr></tbody></table></div><footer><span>共 {{report.total}} 个用户</span><select v-model.number="size"><option :value="20">20条</option><option :value="50">50条</option><option :value="100">100条</option></select><button :disabled="page<=1" @click="page--">上一页</button><span>{{page}} / {{pages}}</span><button :disabled="page>=pages" @click="page++">下一页</button></footer></section>
   </template>
  </template>
  <Teleport to="body"><div v-if="selected" class="audit-backdrop" @click.self="selected=null"><section class="audit-dialog" role="dialog" aria-modal="true" aria-label="客户端用户对账详情"><header><div><h2>{{selected.email}}</h2><p>#{{selected.id}} · {{states[selected.state]}}</p></div><button @click="selected=null" aria-label="关闭"><X :size="20"/></button></header><div class="notes"><p v-for="reason in selected.reasons" :key="reason">{{reason}}</p><p v-if="selected.snapshot_from">快照区间 {{time(selected.snapshot_from)}}—{{time(selected.snapshot_to)}}：消费 {{selected.snapshot_cost}}，入账 {{selected.snapshot_credits}}。这不是缺失历史期初余额的反向估算。</p></div><div class="tabs"><button v-for="[key,label] in [['usage','使用明细'],['funding','充值 / 调整'],['affiliate','返利'],['payment','支付 / 退款'],['key','Key额度'],['subscription','套餐']]" :key="key" :class="{active:entity===key}" @click="entity=key">{{label}}</button></div><p v-if="detailBusy">读取本地明细…</p><div class="detail-list"><details v-for="row in detail" :key="row.id"><summary><span>#{{row.id}}</span><span>{{time(row.used_at||row.created_at)}}</span><b>{{row.model||row.type||row.action||row.order_type}}</b><span>{{row.actual_cost??row.value??row.amount??''}}</span></summary><pre>{{JSON.stringify(row,null,2)}}</pre></details><p v-if="!detail.length&&!detailBusy">当前范围没有已同步明细，或已超过明细保留期。</p></div><button v-if="detailMore" class="btn ghost" :disabled="detailBusy" @click="loadDetail(true)">加载更多</button></section></div></Teleport>
 </div>
</template>

